/* ---------- AC2.5 Laypeople ---------- */
TOPICS.push({
  id: '3.2.5', unit: '3', ref: 'AC2.5', title: 'Laypeople in criminal cases',
  short: 'Juries and magistrates: selection, role, strengths and weaknesses',
  summary: 'Ordinary people — juries in the Crown Court and lay magistrates in the magistrates’ courts — decide most criminal cases in England and Wales. This criterion asks you to discuss the strengths and weaknesses of using laypeople.',
  spec: ['Juries', 'Magistrates', 'Strengths and weaknesses of both juries and lay magistrates'],
  learn: [
    { h: 'Juries', html: `
<ul><li><b>Eligibility</b> (Juries Act 1974): aged 18–75, on the electoral register, lived in the UK for at least five years since age 13. Disqualified: some people with criminal convictions, people on bail, and some people with mental disorders.</li>
<li><b>Selection</b>: random selection from the electoral register; 12 jurors sworn in for a trial. Excusals for good reason; deferral possible.</li>
<li><b>Role</b>: decide the facts and give the verdict — guilty or not guilty — in Crown Court trials. The judge decides the law and the sentence. Majority verdicts of 10–2 or 11–1 are allowed.</li>
<li><b>Secrecy</b>: jury deliberations are secret; jurors must not research the case online ([[c:fraill]]; Juries Act 1974 as amended in 2015).</li>
<li>Trials without a jury are possible where there is a danger of jury tampering ([[c:twomey]]).</li></ul>` },
    { h: 'Lay magistrates', html: `
<ul><li>Unpaid volunteers (justices of the peace) aged 18 or over, appointed by the Lord Chancellor on the advice of local advisory committees; they must retire at 75 (raised from 70 in 2022). There are around 14,000 in England and Wales.</li>
<li>Six key qualities: good character, understanding and communication, social awareness, maturity and sound temperament, sound judgement, commitment and reliability.</li>
<li>Training by the Judicial College; sit in benches of three (or two), advised on law by a legal adviser.</li>
<li>Hear over 90% of criminal cases: summary trials, early hearings, bail, sentencing up to 12 months for one either-way offence, youth court.</li></ul>` },
    { h: 'Strengths and weaknesses', html: `
<div class="tbl"><table><tr><th></th><th>Strengths</th><th>Weaknesses</th></tr>
<tr><td><b>Juries</b></td><td>Public participation and confidence; random and independent; jury equity ([[c:ponting]]); twelve views balance individual bias; secrecy allows free discussion</td><td>No reasons given, so verdicts cannot be scrutinised; may not understand complex evidence (fraud); media and internet influence; racial and other bias; perverse verdicts; costly and slow; jury tampering</td></tr>
<tr><td><b>Magistrates</b></td><td>Cheap (unpaid); local knowledge; legal adviser ensures legal accuracy; panels of three balance views; more diverse than the professional judiciary in gender</td><td>Inconsistent sentencing between benches; may be “case-hardened” and prosecution-minded; not fully representative (older, middle-class); reliance on the legal adviser; declining numbers</td></tr></table></div>` }
  ],
  debate: [{ q: 'Should the use of juries be reduced?', for: ['Court backlogs mean long delays for victims and defendants.', 'Complex fraud trials are hard for juries.', 'Jury tampering and online research risks.', 'Leveson’s 2025 review proposed judge-led benches for some cases.'], ag: ['Jury trial is a constitutional safeguard and a symbol of democracy.', 'Juries can protect against unjust laws (Ponting).', 'Research by Cheryl Thomas (2010) found juries were generally fair and efficient.', 'Removing juries may reduce public confidence.'] }],
  cases: ['fraill', 'twomey', 'ponting'],
  worked: [],
  pitfalls: ['Describing juries and magistrates without discussing strengths and weaknesses — band 1.', 'Mixing up juries’ and magistrates’ roles (magistrates decide both verdict and sentence).'],
  cards: [
    ['Jury eligibility?', '18–75, on the electoral register, lived in the UK 5 years since age 13 (Juries Act 1974).'],
    ['How many jurors?', '12; majority verdicts of 10–2 or 11–1 allowed.'],
    ['Who appoints magistrates?', 'The Lord Chancellor, on the advice of local advisory committees.'],
    ['Magistrates’ retirement age?', '75 (since 2022).'],
    ['What is jury equity?', 'Acquitting against the law because the jury thinks a prosecution is unjust (Ponting).'],
    ['What happened in R v Fraill?', 'A juror contacted a defendant on Facebook and was jailed for contempt.'],
    ['What was R v Twomey?', 'The first Crown Court trial without a jury because of jury tampering (CJA 2003 s44).'],
    ['Two weaknesses of magistrates?', 'Inconsistent sentencing; case-hardened/prosecution-minded; not representative.']
  ],
  quiz: [
    { q: 'Jurors are selected from…', o: ['the electoral register', 'volunteers', 'police lists', 'local councils'], x: 'Random selection.' },
    { q: 'Magistrates are advised on the law by…', o: ['a legal adviser', 'the jury', 'the CPS', 'the defendant'], x: 'Formerly called a clerk.' },
    { q: 'Which is a strength of juries?', o: ['Public participation in justice', 'They give detailed reasons', 'They are cheap', 'They are experts in law'], x: '' },
    { q: 'A weakness of lay magistrates is…', o: ['inconsistent sentencing between areas', 'they are paid high salaries', 'they sit alone without advice', 'they decide murder trials'], x: '' }
  ],
  exam: [{ q: 'Practice task: discuss the strengths and weaknesses of juries and lay magistrates. [6]', m: 6, ms: ['juries — selection, role; strengths (participation, equity); weaknesses (no reasons, bias, internet, complexity)', 'magistrates — selection, role; strengths (cost, local knowledge); weaknesses (inconsistency, case-hardening, representativeness)', 'cases (Fraill, Twomey, Ponting)', 'balanced discussion'], bands: U3_BANDS['2.5'] }],
  tools: ['laysort']
});

/* ---------- AC3.1 Examining information for validity ---------- */
TOPICS.push({
  id: '3.3.1', unit: '3', ref: 'AC3.1', title: 'Examining information for validity',
  short: 'Examining evidence, trial transcripts, media reports, judgements and law reports for bias, opinion, circumstances, currency and accuracy',
  summary: 'To review a criminal case you must judge how far you can trust each source of information. This criterion asks you to examine sources — evidence, trial transcripts, media reports, judgements and law reports — for bias, opinion, circumstances, currency and accuracy, with reference to the assignment brief and other cases you have studied.',
  spec: ['Examine for bias, opinion, circumstances, currency, accuracy', 'Information: evidence, trial transcripts, media reports, judgements, Law Reports', 'Refer to the assignment brief and other examples studied'],
  learn: [
    { h: 'The five criteria', html: `
<div class="tbl"><table><tr><th>Criterion</th><th>Questions to ask</th></tr>
<tr><td><b>Bias</b></td><td>Does the source favour one side? Who produced it and why? (A campaign website, a tabloid, the police, the defendant’s family)</td></tr>
<tr><td><b>Opinion</b></td><td>Is it fact or someone’s view? Is the opinion from a qualified expert?</td></tr>
<tr><td><b>Circumstances</b></td><td>Under what conditions was it produced? (A confession after hours in custody; a witness who saw the event at night; a report written during a moral panic)</td></tr>
<tr><td><b>Currency</b></td><td>How up to date is it? Has later evidence (e.g. DNA) or a later appeal superseded it?</td></tr>
<tr><td><b>Accuracy</b></td><td>Is it correct and complete? Can it be checked against other sources? Are there errors or omissions?</td></tr></table></div>` },
    { h: 'Types of information', html: `
<ul><li><b>Evidence</b> — physical and testimonial evidence (AC1.3). Consider contamination, chain of continuity and the circumstances in which statements were taken.</li>
<li><b>Trial transcripts</b> — a verbatim record of what was said in court; accurate but may be incomplete (excerpts), and the evidence itself may have been challenged later.</li>
<li><b>Media reports</b> — may be biased, sensational, based on police or family sources, and written before all facts were known ([[c:jefferies]]; [[c:sunhillsborough]]).</li>
<li><b>Judgements</b> — the reasoned decisions of judges, especially appeal judgements; authoritative and usually accurate, but reflect the evidence available at that time.</li>
<li><b>Law Reports</b> — official, edited reports of important cases; highly reliable, focused on legal points rather than all the facts.</li></ul>` },
    { h: 'Writing the examination', html: `<p>For the top band: examine a <b>relevant range</b> of sources in <b>detail</b>, refer to the <b>brief</b>, and give a clear review of <b>suitability</b>. For each source, apply several criteria and reach a judgement: “This newspaper report is of limited validity because it was written before the trial, relies on an anonymous police source and uses emotive language; however, its account of the timeline is confirmed by the court judgement.”</p>` }
  ],
  debate: [],
  cases: ['jefferies', 'sunhillsborough', 'barrygeorge'],
  worked: [],
  pitfalls: ['Describing sources without judging validity.', 'Using only one criterion (usually bias).', 'Not referring to the assignment brief — required for the top band.'],
  cards: [
    ['Five validity criteria in AC3.1?', 'Bias, opinion, circumstances, currency, accuracy.'],
    ['Five types of information in AC3.1?', 'Evidence, trial transcripts, media reports, judgements, Law Reports.'],
    ['What does currency mean?', 'How up to date the information is — has it been superseded?'],
    ['Why are Law Reports highly valid?', 'Official, edited and accurate reports of judicial decisions.'],
    ['Why might a media report lack validity?', 'Bias, sensationalism, reliance on one source, written before facts known.']
  ],
  quiz: [
    { q: 'A 2001 report saying a conviction is safe, when it was quashed in 2007, fails on…', o: ['currency', 'accuracy of spelling', 'opinion', 'bias only'], x: 'Out of date.' },
    { q: 'A confession given after 13 hours of hostile questioning raises concerns about…', o: ['circumstances', 'currency', 'Law Reports', 'relevance'], x: 'How it was produced.' },
    { q: 'Which source is usually most authoritative on the law?', o: ['A Law Report', 'A tabloid', 'A blog', 'A campaign leaflet'], x: '' }
  ],
  exam: [{ q: 'Practice task: examine the validity of three sources about a case you have studied. [15]', m: 15, ms: ['relevant range of sources (e.g. media report, appeal judgement, expert evidence)', 'each examined for bias, opinion, circumstances, currency, accuracy', 'comparison between sources', 'reference to the brief/case facts', 'clear review of suitability'], bands: U3_BANDS['3.1'] }],
  tools: ['validitysort']
});

/* ---------- AC3.2 Drawing conclusions ---------- */
TOPICS.push({
  id: '3.3.2', unit: '3', ref: 'AC3.2', title: 'Drawing conclusions about criminal cases',
  short: 'Just verdicts, miscarriages of justice, safe verdicts and just sentencing',
  summary: 'The final criterion in Unit 3 asks you to use the information you have examined to reach objective, reasoned conclusions about a criminal case: was the verdict just and safe, was there a miscarriage of justice, and was the sentence just?',
  spec: ['Just verdicts', 'Miscarriage of justice', 'Safe verdict', 'Just sentencing', 'Draw conclusions based on reasoned evidence, with reference to the assignment brief and other examples'],
  learn: [
    { h: 'Key concepts', html: `
<ul><li><b>Just verdict</b> — the guilty are convicted and the innocent acquitted, through a fair process.</li>
<li><b>Safe verdict</b> — a conviction the Court of Appeal would not quash; there is no reason to doubt it. A conviction is <b>unsafe</b> if, for example, key evidence was flawed, not disclosed or wrongly admitted, or the judge misdirected the jury (Criminal Appeal Act 1995).</li>
<li><b>Miscarriage of justice</b> — usually the conviction of an innocent person, but also a guilty person going free, or an unfair process. Examples: [[c:birminghamsix]], [[c:kiszko]], [[c:sallyclark]], [[c:malkinson]], [[c:postoffice]].</li>
<li><b>Just sentencing</b> — proportionate to the seriousness of the offence (culpability and harm), consistent with Sentencing Council guidelines, and meeting the purposes of sentencing (s57 Sentencing Act 2020). Unjust sentences: [[c:ipp]]; unduly lenient sentences referred by the Attorney General.</li></ul>` },
    { h: 'Common causes of miscarriages of justice', html: `<ul><li>False confessions and oppressive interviews ([[c:cardiffthree]])</li><li>Eyewitness misidentification ([[c:malkinson]])</li><li>Flawed or misrepresented forensic and expert evidence ([[c:barrygeorge]]; [[c:meadow]])</li><li>Non-disclosure ([[c:kiszko]]; [[c:liamallan]])</li><li>Police misconduct and pressure to convict ([[c:guildford]])</li><li>Media prejudice ([[c:jefferies]])</li><li>Faulty technology treated as reliable ([[c:postoffice]])</li></ul>` },
    { h: 'Reaching objective conclusions', html: `
<ol><li>Summarise the <b>key evidence for and against</b> the verdict.</li><li>Weigh it using your <b>validity</b> review (AC3.1).</li><li>Consider the <b>process</b>: rights, disclosure, rules of evidence, influences (LO2).</li><li>Reach a <b>clear judgement</b> on whether the verdict is safe and just and whether the sentence is just.</li><li>Acknowledge <b>uncertainty</b> — an acquittal is not proof of innocence ([[c:jenkins]]).</li><li>Refer to the <b>brief</b> and <b>other cases</b> for comparison.</li></ol>` }
  ],
  debate: [{ q: 'Is the appeals system effective at correcting miscarriages of justice?', for: ['The CCRC has referred hundreds of cases, many quashed.', 'Courts have quashed convictions in landmark cases (Birmingham Six, Sally Clark).', 'DNA can later identify the real offender (Cardiff Three, Kiszko).'], ag: ['It can take decades (Malkinson: 17 years).', 'The CCRC’s “real possibility” test is cautious.', 'Post Office cases needed an Act of Parliament.', 'Legal aid cuts make appeals harder to bring.'] }],
  cases: ['malkinson', 'postoffice', 'ipp', 'jenkins', 'ccrc', 'birminghamsix', 'cardiffthree'],
  worked: [],
  pitfalls: ['Subjective conclusions (“I think he’s guilty”) with no evidence — band 1.', 'Confusing “not guilty” with “innocent”.', 'Ignoring sentencing — just sentencing is in the specification.'],
  cards: [
    ['What is a miscarriage of justice?', 'Usually the conviction of an innocent person; also the guilty escaping or an unfair process.'],
    ['When is a conviction unsafe?', 'When there is reason to doubt it — flawed evidence, non-disclosure, misdirection.'],
    ['What is just sentencing?', 'Proportionate, consistent with guidelines and meeting the purposes of sentencing.'],
    ['What does the CCRC do?', 'Reviews possible miscarriages of justice and refers cases to the appeal courts (since 1997).'],
    ['Why is IPP seen as unjust?', 'People stayed in prison years beyond short minimum terms; not abolished retrospectively.'],
    ['How long did Andrew Malkinson serve before his conviction was quashed?', '17 years.']
  ],
  quiz: [
    { q: 'The CCRC refers a case if there is…', o: ['a real possibility the conviction will be quashed', 'certain proof of innocence', 'media interest', 'a new judge'], x: 'Criminal Appeal Act 1995.' },
    { q: 'A “not guilty” verdict means…', o: ['the prosecution did not prove guilt beyond reasonable doubt', 'the defendant is proven innocent', 'the case can never be revisited', 'the jury was biased'], x: 'Jenkins.' },
    { q: 'Which is a common cause of miscarriages of justice?', o: ['Eyewitness misidentification', 'Accurate DNA', 'Full disclosure', 'Special measures'], x: 'Malkinson.' }
  ],
  exam: [{ q: 'Practice task: draw conclusions on whether the verdict in a case you have studied was safe and just, and whether the sentence was just. [15]', m: 15, ms: ['summary of key evidence for and against', 'validity of the evidence weighed', 'process issues — rights, disclosure, rules of evidence, influences', 'clear, objective judgement on safety and justice of verdict', 'judgement on sentencing', 'comparison with other cases; reference to the brief'], bands: U3_BANDS['3.2'] }],
  tools: ['safetree']
});

